import React, { forwardRef, ReactNode } from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { TooltipBaseProps, Tooltip } from '../../overlays/tooltip/Tooltip.js';
import { Text } from '../../typography/Text.js';
import { KeyboardShortcut } from '../keyboard-shortcut/KeyboardShortcut.js';
// #region Typings
/** Accepted properties for KeyboardShortcutTooltip */
export interface KeyboardShortcutTooltipProps
  extends TooltipBaseProps,
    StylingProps,
    DataTestId {
  /**
   * The list of keys the component should display, specified in the aria-keyshortcuts format.
   */
  keys: string;

  /**
   * Whether the component should be rendered in a disabled state.
   * @defaultValue 'false'
   */
  shortcutDisabled?: boolean;

  /** Text displayed in the tooltip component. */
  text?: ReactNode;
}
// #endregion Typings

// #region StyledComponents
const StyledText = /* @__PURE__ */ styled(Text)({
  maxWidth: '100%',
  overflowWrap: 'anywhere',
});
// #endregion StyledComponents

/**
 * Use the `KeyboardShortcutTooltip` component to display a `KeyboardShortcut` along with an optional text inside a tooltip.
 * The `KeyboardShortcutTooltip` opens on hover and click on its trigger element.
 * The trigger element can only be an interactive element, like a button or input.
 */
export const KeyboardShortcutTooltip = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  KeyboardShortcutTooltipProps
>((props: KeyboardShortcutTooltipProps, forwardedRef) => {
  const {
    children,
    keys,
    shortcutDisabled,
    text,
    placement = 'top',
    open,
    defaultOpen,
    onOpenChange,
    delay = 'default',
    disabled,
    style: consumerStyle,
    className: consumerClassName,
    'data-testid': dataTestId,
  } = props;

  return (
    <Tooltip
      ref={forwardedRef}
      placement={placement}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      delay={delay}
      disabled={disabled}
      data-testid={dataTestId}
      className={consumerClassName}
      style={consumerStyle}
      text={
        <Flex flexDirection="column" alignItems="center" gap={4}>
          {text && <StyledText textStyle="small-emphasized">{text}</StyledText>}
          <KeyboardShortcut
            keys={keys}
            variant="minimal"
            color="onaccent"
            disabled={shortcutDisabled}
          ></KeyboardShortcut>
        </Flex>
      }
    >
      {children}
    </Tooltip>
  );
});
(
  KeyboardShortcutTooltip as typeof KeyboardShortcutTooltip & {
    displayName: string;
  }
).displayName = 'KeyboardShortcutTooltip';
